// Agentic platform types

export interface Plugin {
  id: string;
  name: string;
  version: string;
  applicationId: string;
  enabled: boolean;
  config: Record<string, unknown>;
  hooks: PluginHooks;
  metadata: Record<string, unknown>;
}

export interface PluginHooks {
  onApplicationStart?: () => Promise<void>;
  onApplicationStop?: () => Promise<void>;
  onUserLogin?: (userId: string) => Promise<void>;
  onUserLogout?: (userId: string) => Promise<void>;
  onApplicationEnable?: (userId: string, applicationId: string) => Promise<void>;
  onApplicationDisable?: (userId: string, applicationId: string) => Promise<void>;
  [key: string]: ((...args: unknown[]) => Promise<void>) | undefined;
}

export interface Event {
  id: string;
  type: string;
  source: string;
  target?: string;
  payload: Record<string, unknown>;
  timestamp: Date;
  metadata?: Record<string, unknown>;
}

export interface EventHandler {
  eventType: string;
  handler: (event: Event) => Promise<void>;
  applicationId: string;
}

export interface ApplicationLifecycleHook {
  applicationId: string;
  hook: 'beforeStart' | 'afterStart' | 'beforeStop' | 'afterStop';
  handler: () => Promise<void>;
}
